namespace SupremeCommanderOverhaulCanonical;

internal static class NavalWreckMotionPolicy
{
	private const string Marker = "-- SCOM naval seabed settling 2.0.0";

	internal static string Patch(string source)
	{
		source = source.Replace("\r\n", "\n");
		source = SCO_RepairMigrateWreck24(source);
		if (source.Contains("-- SCOM naval seabed settling 2.4.0"))
