		{
			throw new InvalidOperationException("Mixed or foreign SCOM naval death timing source contract.");
		}
		if (source.Contains("local function startNavalWreck"))
		{
			throw new InvalidOperationException("Mixed or foreign SCOM naval death timing source contract.");
		}
		if (source.Contains("self.OnSpawnWreckage ="))
